'use strict';
const normalizeText=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const INGREDIENT_ALIASES={pork:['pork','thit heo','thit lon','pork mince'],ribs:['pork ribs','suon'],chicken:['chicken breast','chicken thigh','chicken fillet','thit ga','chicken','dui ga','canh ga','drumstick','drumsticks'],beef:['beef','thit bo'],salmon:['salmon','ca hoi'],fish:['basa','white fish','barramundi','ca trang','fish fillet'],shrimp:['prawn','shrimp','tom'],tofu:['tofu','dau hu','dau phu'],egg:['eggs','egg','trung'],rice:['rice','gao'],noodle:['rice vermicelli','bun tuoi','bun'],spinach:['spinach','rau cai','choy sum'],waterSpinach:['water spinach','rau muong','ong choy'],cabbage:['cabbage','bap cai'],bokchoy:['bok choy','pak choy','cai thia'],broccoli:['broccoli','bong cai'],carrot:['carrot','ca rot'],potato:['potato','khoai tay'],pumpkin:['pumpkin','bi do'],gourd:['winter melon','bi xanh'],tomato:['tomato','ca chua'],cucumber:['cucumber','dua leo'],mushroom:['mushroom','nam'],onion:['onion','hanh tay'],scallion:['spring onion','shallot','hanh la'],garlic:['garlic','toi'],ginger:['ginger','gung'],lemongrass:['lemongrass','sa'],pineapple:['pineapple','dua'],okra:['okra','dau bap'],bean:['green beans','dau que'],fishSauce:['fish sauce','nuoc mam'],soy:['soy sauce','nuoc tuong','xi dau'],oil:['cooking oil','vegetable oil','dau an'],sugar:['sugar','duong'],salt:['salt','muoi'],pepper:['pepper','tieu'],coconut:['coconut water','nuoc dua'],broth:['chicken stock','beef stock','nuoc dung'],vegBroth:['vegetable stock','nuoc dung rau cu'],riceNoodle:['pho noodles','banh pho'],huTieu:['hu tieu'],banhCanh:['banh canh'],eggNoodle:['egg noodle','mi trung'],vermicelli:['glass noodle','mien kho'],udon:['udon'],corn:['sweet corn','corn','bap hat'],peas:['peas','dau ha lan'],wonton:['wonton','hoanh thanh'],fishBall:['fish ball','ca vien'],cookedChicken:['roast chicken','cooked chicken','ga chin'],seaweed:['seaweed','rong bien'],miso:['miso'],starch:['corn flour','cornflour','corn starch','bot bap'],lime:['lime','lemon','chanh'],herbs:['coriander','herbs','rau thom'],pasta:['pasta','macaroni','nui'],cookedRice:['cooked rice','com chin']};
function inferIngredient(label,state,preferred=[]){const n=normalizeText(label);const learned=state.aliases?.[n];if(learned&&(learned==='other'||Object.hasOwn(INGREDIENTS,learned)||learned.startsWith('recipe:')&&state.recipes.some(r=>'recipe:'+r.id===learned)))return {match:learned,confidence:'learned'};let best='',score=0;for(const [id,i]of Object.entries(INGREDIENTS)){const names=[normalizeText(i[0]),...(INGREDIENT_ALIASES[id]||[])];for(const alias of names){if(!alias)continue;const exact=n===alias,word=(' '+n+' ').includes(' '+alias+' ');const s=exact?100:word?alias.length+5:0;if(s>score){best=id;score=s}}}for(const r of state.recipes){const name=normalizeText(r.name);if(n===name||(name.length>7&&n.includes(name)&&name.length+10>score)){best='recipe:'+r.id;score=100}}return{match:best||'',confidence:score>=100?'name':score>0?'suggested':'unknown'}}
function quantityFromText(text){const match=String(text).match(/(\d+(?:[.,]\d+)?)\s*(kg|kilograms?|kilogram|grams?|gram|g|ml|litres?|liters?|lit|lít|l|quả|qua|eggs?|cái|cai|bó|bo|hộp|hop|chai|gói|goi|miếng|mieng|khay|túi|tui|con|pcs?|pack)(?=\s|$|[,;:])/iu);if(!match)return{qty:null,unit:''};let qty=Number(match[1].replace(',','.')),unit=normalizeText(match[2]);if(unit.startsWith('kilo'))unit='kg';if(['gram','grams'].includes(unit))unit='g';if(['litre','litres','liter','liters','lit'].includes(unit))unit='l';if(['qua','egg','eggs'].includes(unit))unit='quả';const labels={cai:'cái',bo:'bó',mieng:'miếng',goi:'gói',hop:'hộp',tui:'túi',chai:'chai',khay:'khay',con:'con',pc:'cái',pcs:'cái',pack:'gói'};unit=labels[unit]||unit;return{qty,unit}}
function canonicalQuantity(qty,unit,id){if(qty===null||!Number.isFinite(qty)||qty<=0||!INGREDIENTS[id])return null;const base=INGREDIENTS[id][1];if(base==='g'&&(unit==='g'||unit==='kg'))return qty*(unit==='kg'?1000:1);if(base==='ml'&&(unit==='ml'||unit==='l'))return qty*(unit==='l'?1000:1);if(base==='quả'&&unit==='quả'&&Number.isInteger(qty))return qty;return null}
function parseShoppingNotes(text,state){return String(text).split('\n').map(s=>s.replace(/^\s*(?:[-*•☐☑✓✔]|\[[ xX]\]|\d+[.)])\s*/,'').trim()).filter(Boolean).map(raw=>{const inferred=inferIngredient(raw.replace(/\d+(?:[.,]\d+)?\s*(?:kg|g|ml|l|quả|qua|bó|bo|hộp|hop|chai|gói|goi)\b/giu,''),state);return{id:uid(),raw,match:inferred.match.startsWith('recipe:')?'':inferred.match,...quantityFromText(raw),include:true}})}
function parseReceiptText(text,state){const lines=String(text).split('\n').map(s=>s.trim()).filter(Boolean);const items=[];let total=null,pending='';const dateMatch=String(text).match(/\b(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})\b/);let date=sydneyDate();if(dateMatch){const y=dateMatch[3].length===2?'20'+dateMatch[3]:dateMatch[3];const guess=`${y}-${dateMatch[2].padStart(2,'0')}-${dateMatch[1].padStart(2,'0')}`;if(!isNaN(parseDate(guess)))date=guess}for(const line of lines){const normalized=normalizeText(line);const priceMatch=line.match(/(-?\$?\s*\d+[.,]\d{2})\s*(?:[A-Za-z*])?\s*$/);if(/^(grand total|total|amount due|tong cong|tong tien)\b/.test(normalized)&&!/^total savings/.test(normalized)){if(priceMatch)total=Number(priceMatch[1].replace(/[$\s]/g,'').replace(',','.'));continue}if(/^(sub ?total|gst|tax|cash|change|eftpos|visa|mastercard|card|savings|total savings|abn|tel|phone|receipt|invoice|transaction|terminal|approved|balance|thank|you saved|payment|discount total)\b/.test(normalized)||/\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b/.test(line)){pending='';continue}if(!priceMatch){if(/[A-Za-zÀ-ỹ]/.test(line)&&line.length<130)pending=line;continue}let label=line.slice(0,priceMatch.index).replace(/\s+[$*]$/,'').trim();if(!label&&pending)label=pending;pending='';if(!label||!/[A-Za-zÀ-ỹ]/.test(label))continue;const cost=Number(priceMatch[1].replace(/[$\s]/g,'').replace(',','.'));if(!Number.isFinite(cost))continue;const inferred=inferIngredient(label,state);items.push({id:uid(),label,total:cost,match:inferred.match,confidence:inferred.confidence,...quantityFromText(label),include:true})}return{store:lines[0]&&lines[0].length<70&&!/\d+[.,]\d{2}\s*$/.test(lines[0])?lines[0]:'',date,total:total??Math.round(items.reduce((n,i)=>n+i.total,0)*100)/100,items}}
function receiptTotal(receipt){return Number(receipt.total)||0}
function receiptsInWeek(state,start){return(state.receipts||[]).filter(r=>r.date>=start&&r.date<=addDays(start,6))}
function unitPrice(item){if(!item.ingredient||!INGREDIENTS[item.ingredient]||item.total<=0)return null;if(Number.isFinite(item.quantity)&&item.quantity>0){const unit=INGREDIENTS[item.ingredient][1],factor=['g','ml'].includes(unit)?1000:1;return{value:item.total/item.quantity*factor,unit:unit==='g'?'kg':unit==='ml'?'l':'quả'}}if(Number.isFinite(item.enteredQty)&&item.enteredQty>0&&typeof item.enteredUnit==='string'&&item.enteredUnit&&!['g','kg','ml','l','pack'].includes(item.enteredUnit))return{value:item.total/item.enteredQty,unit:item.enteredUnit};return null}

function priceHistory(state){const groups={};for(const receipt of state.receipts||[])for(const item of receipt.items||[]){const price=unitPrice(item);if(!price)continue;const key=item.ingredient+'|'+normalizeText(receipt.store)+'|'+price.unit;(groups[key]??=[]).push({ingredient:item.ingredient,store:receipt.store,date:receipt.date,createdAt:receipt.createdAt||'',label:item.label,...price})}return Object.values(groups).map(rows=>{rows.sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt));const last=rows.at(-1),previous=rows.at(-2);return{...last,previous:previous?.value??null,change:previous?(last.value/previous.value-1)*100:null,count:rows.length}}).sort((a,b)=>(b.change??-Infinity)-(a.change??-Infinity))}
function validSpending(s){
 const itemOK=i=>i&&typeof i.id==='string'&&typeof i.label==='string'&&Number.isFinite(i.total)&&Math.abs(i.total)<1e7&&(!i.ingredient||Object.hasOwn(INGREDIENTS,i.ingredient))&&(!i.recipe||typeof i.recipe==='string')&&(i.quantity===null||(Number.isFinite(i.quantity)&&i.quantity>0&&i.quantity<=1e6));
 const receiptOK=r=>r&&typeof r.id==='string'&&typeof r.store==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Number.isFinite(r.total)&&r.total>=0&&r.total<1e7&&Array.isArray(r.items)&&r.items.every(itemOK);
 if(s.receipts!==undefined&&(!Array.isArray(s.receipts)||!s.receipts.every(receiptOK)))return false;
 if(s.aliases!==undefined&&(!s.aliases||Array.isArray(s.aliases)||typeof s.aliases!=='object'||!Object.values(s.aliases).every(v=>typeof v==='string'&&(v==='other'||Object.hasOwn(INGREDIENTS,v)||v.startsWith('recipe:')))))return false;
 return true;
}
